begin;set local lock_timeout='3s';set local statement_timeout='60s';
create temporary table q_test(actor uuid,sicurezza_actor uuid,azienda uuid,ordine uuid,hr uuid default gen_random_uuid(),altro_hr uuid default gen_random_uuid(),sub uuid default gen_random_uuid(),operaio uuid default gen_random_uuid(),doc_hr uuid default gen_random_uuid(),doc_privato uuid default gen_random_uuid(),doc_ext uuid default gen_random_uuid(),r1 uuid default gen_random_uuid(),r2 uuid default gen_random_uuid(),r3 uuid default gen_random_uuid(),dati jsonb,fonte jsonb,ricevuta jsonb);
insert into q_test(actor,sicurezza_actor,azienda,ordine,dati)select sp.id,sf.user_id,sf.company_id,o.id,'{"tipologia":"abilitazione","titolo":"TEST PLE","ambito":"TEST PLE semovente","ente":"Ente TEST","validita_dal":"2026-11-01","validita_al":"2027-10-31","motivazione_senza_scadenza":"","limitazioni":"TEST condizioni","riferimento":"TEST lettura diretta","conferma_lettura":true}'::jsonb from public.profiles sp join public.staff_permissions sf on public.has_permission_for_company(sp.id,'can_view_persone',sf.company_id) and sf.can_view_sicurezza_cantiere and not sf.can_view_persone and not public.has_role(sf.user_id,'super_admin'::public.app_role) and not public.has_role(sf.user_id,'company_admin'::public.app_role) and not exists(select 1 from public.multi_company_access m where m.user_id=sf.user_id and m.company_id=sf.company_id and m.status='active' and m.access_role::text='company_admin') join public.orders o on o.company_id=sf.company_id and o.deleted_at is null where public.has_permission_for_company(sp.id,'can_view_persone',sf.company_id) and public.has_permission_for_company(sp.id,'can_view_sicurezza_cantiere',sf.company_id) limit 1;
grant select,update on q_test to authenticated;
do $$begin if not exists(select 1 from q_test) then raise exception 'Fixture qualifiche priva di autore autorizzato';end if;end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true)from q_test;
insert into public.hr_profili(id,company_id,nome,cognome)select x.id,f.azienda,'TEST QUALIFICA','Omonimo' from q_test f cross join lateral(values(f.hr),(f.altro_hr))x(id);
insert into public.subappaltatori_sicurezza(id,company_id,order_id,ragione_sociale)select sub,azienda,ordine,'TEST QUALIFICHE IMPRESA' from q_test;
insert into public.subappaltatori_operai(id,company_id,subappaltatore_id,nome,cognome,mansione)select operaio,azienda,sub,'TEST QUALIFICA','Omonimo','TEST Addetto' from q_test;
insert into public.hr_documenti(id,company_id,hr_profilo_id,categoria,titolo,ente,data_rilascio,data_scadenza,file_name,file_path,note)select doc_hr,azienda,hr,'corso_sicurezza','TEST PLE originale','TEST ente','2026-11-01','2027-10-31','TEST PLE.pdf',azienda::text||'/'||hr::text||'/qualifica.pdf','TEST NOTA HR RISERVATA' from q_test;
insert into public.hr_documenti(id,company_id,hr_profilo_id,categoria,titolo,file_name,file_path,note)select doc_privato,azienda,hr,'visita_medica','TEST DATO SANITARIO','TEST RISERVATO.pdf',azienda::text||'/'||hr::text||'/privato.pdf','TEST RISERVATO' from q_test;
insert into storage.objects(bucket_id,name,version,metadata)select 'fascicoli-cantiere',azienda::text||'/'||doc_ext::text||'/esterno.pdf','TEST QUALIFICHE 1','{"size":10,"eTag":"TEST"}'::jsonb from q_test;
insert into public.sicurezza_fascicolo(id,company_id,subappaltatore_id,operaio_id,tipo,titolo,stato,file_name,file_path,data_rilascio,data_scadenza)select doc_ext,azienda,sub,operaio,'formazione','TEST PLE esterno','ricevuto','TEST PLE esterno.pdf',azienda::text||'/'||doc_ext::text||'/esterno.pdf','2026-11-01','2027-10-31' from q_test;
insert into storage.objects(bucket_id,name,version,metadata)select 'hr-documenti',file_path,'TEST QUALIFICHE 1','{"size":10,"eTag":"TEST"}' from public.hr_documenti where id in(select doc_hr from q_test union all select doc_privato from q_test);

create temporary table contesto_test(ordine uuid default gen_random_uuid(),fase uuid default gen_random_uuid(),altra_fase uuid default gen_random_uuid(),employee uuid default gen_random_uuid(),non_collegato uuid default gen_random_uuid(),esterno_legacy uuid default gen_random_uuid(),altro_operaio uuid default gen_random_uuid(),quadro jsonb,profilo uuid default gen_random_uuid(),criterio uuid default gen_random_uuid(),verifica uuid default gen_random_uuid(),verifica2 uuid default gen_random_uuid(),dati_riesame jsonb,mezzo uuid default gen_random_uuid());
insert into contesto_test default values;grant select,update on contesto_test to authenticated;
insert into public.orders(id,company_id,description,work_start_date,work_end_date,weekly_report_enabled,giornale_auto_enabled)select c.ordine,t.azienda,'TEST REQUISITI ADDETTI','2026-11-01','2026-11-30',false,false from contesto_test c cross join q_test t;
insert into public.order_work_phases(id,company_id,order_id,name,position,start_date,end_date)select v.id,t.azienda,c.ordine,'TEST FASE ADDETTI',v.pos,'2026-11-01','2026-11-30' from contesto_test c cross join q_test t cross join lateral(values(c.fase,0),(c.altra_fase,1))v(id,pos);
insert into public.employees(id,company_id,first_name,last_name,qualifica,role_type,gross_salary)select v.id,t.azienda,'TEST ADDETTO','Omonimo','TEST Mansione',v.tipo,987654 from contesto_test c cross join q_test t cross join lateral(values(c.employee,'operaio'),(c.non_collegato,'operaio'),(c.esterno_legacy,'subappaltatore'))v(id,tipo);
update public.hr_profili set employee_id=(select employee from contesto_test),mansione='TEST Mansione',note_interne='TEST DATO HR PRIVATO' where id=(select hr from q_test);
insert into public.order_employees(order_id,employee_id,phase_id)select c.ordine,v.id,c.fase from contesto_test c cross join lateral(values(c.employee),(c.non_collegato),(c.esterno_legacy))v(id);
-- Employee creation also creates canonical HR profiles. Demonstrate ambiguity before isolating the synthetic links.
set local role authenticated;
do $$declare t record;c record;q jsonb;begin select * into t from q_test;select * into c from contesto_test;
 q:=public.sicurezza_addetti_commessa(t.azienda,c.ordine,'2026-11-10','2026-11-15',c.fase);
 if not exists(select 1 from jsonb_array_elements(q->'da_collegare')a where a->>'chiave'='employee:'||c.employee::text and a->>'motivo'='Collegamento HR ambiguo') then raise exception 'ASSERT: due profili HR per la stessa fonte non segnalati';end if;
end$$;
reset role;
update public.hr_profili set employee_id=null where company_id=(select azienda from q_test) and employee_id in(select employee from contesto_test union all select non_collegato from contesto_test) and id<>(select hr from q_test);
insert into public.subappaltatori_operai(id,company_id,subappaltatore_id,nome,cognome,mansione)select c.altro_operaio,t.azienda,t.sub,'TEST ADDETTO','Omonimo','TEST altra fase'from contesto_test c cross join q_test t;
insert into public.subappaltatori_assegnazioni(company_id,order_id,subappaltatore_id,operaio_id,fase_id,dal,al,attivita)select t.azienda,c.ordine,t.sub,v.operaio,v.fase,'2026-11-05','2026-11-20','TEST assegnazione'from contesto_test c cross join q_test t cross join lateral(values(t.operaio,c.fase),(c.altro_operaio,c.altra_fase))v(operaio,fase);
set local role authenticated;
do $$declare t record;c record;q jsonb;f jsonb;begin select * into t from q_test;select * into c from contesto_test;
 f:=public.sicurezza_qualifiche_quadro(t.azienda,'hr',t.hr)->'fonti'->0;
 perform public.sicurezza_qualifica_registra(t.r1,t.azienda,'hr',t.hr,null,'riesamina',t.doc_hr,f->'foto'->>'impronta',t.dati,'');
 f:=public.sicurezza_qualifiche_quadro(t.azienda,'esterno',t.operaio)->'fonti'->0;
 perform public.sicurezza_qualifica_registra(t.r3,t.azienda,'esterno',t.operaio,null,'riesamina',t.doc_ext,f->'foto'->>'impronta',t.dati,'');
 q:=public.sicurezza_addetti_commessa(t.azienda,c.ordine,'2026-11-10','2026-11-15',c.fase);
 if jsonb_array_length(q->'persone')<>2 or jsonb_array_length(q->'da_collegare')<>2 or jsonb_array_length(q->'qualifiche')<>2 then raise exception 'ASSERT: organico/qualifiche esclusi o omonimi uniti';end if;
 if q::text like '%TEST DATO HR PRIVATO%' or q::text like '%987654%' or q::text like '%hr-documenti%' or q::text like '%file_path%' or q::text like '%qualifica.pdf%' then raise exception 'ASSERT: dati HR/file economici proiettati';end if;
 if exists(select 1 from jsonb_array_elements(q->'persone')p where p->>'id'=c.altro_operaio::text) then raise exception 'ASSERT: operaio di altra fase';end if;
 if not exists(select 1 from jsonb_array_elements(q->'persone')p where p->>'id'=t.hr::text and p->'periodi'->0->'senza_date'='true'::jsonb) then raise exception 'ASSERT: assegnazione senza date trasformata in storia';end if;
 if public.sicurezza_addetti_commessa(t.azienda,c.ordine,'2026-11-10','2026-11-15',c.fase)->>'impronta' is distinct from q->>'impronta' then raise exception 'ASSERT: impronta non deterministica';end if;
 perform set_config('TimeZone','Europe/Rome',true);if public.sicurezza_addetti_commessa(t.azienda,c.ordine,'2026-11-10','2026-11-15',c.fase)->>'impronta' is distinct from q->>'impronta' then raise exception 'ASSERT: impronta dipende dal fuso orario';end if;perform set_config('TimeZone','UTC',true);
 update contesto_test set quadro=q;
 begin perform public.sicurezza_addetti_commessa(gen_random_uuid(),c.ordine,'2026-11-10','2026-11-15',c.fase);raise exception 'ASSERT: azienda estranea';exception when insufficient_privilege then null;end;
 begin perform public.sicurezza_addetti_commessa(t.azienda,c.ordine,'2026-11-10','2026-11-15',gen_random_uuid());raise exception 'ASSERT: fase estranea';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 begin perform public.sicurezza_addetti_commessa(t.azienda,c.ordine,'2026-10-31','2026-11-15',c.fase);raise exception 'ASSERT: periodo oltre la fase';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
end$$;
reset role;
-- Another worker in another phase is visible only in the broader case context.
set local role authenticated;
do $$declare t record;c record;q jsonb;begin select * into t from q_test;select * into c from contesto_test;
 q:=public.sicurezza_addetti_commessa(t.azienda,c.ordine,'2026-11-10','2026-11-15',null);
 if jsonb_array_length(q->'persone')<>3 then raise exception 'ASSERT: fase non selezionata esclude addetti';end if;
 q:=public.sicurezza_addetti_commessa(t.azienda,c.ordine,'2026-11-01','2026-11-04',c.fase);
 if exists(select 1 from jsonb_array_elements(q->'persone')p where p->>'tipo'='esterno') then raise exception 'ASSERT: assegnazioni non sovrapposte incluse';end if;
end$$;
reset role;
update public.hr_profili set mansione='TEST mansione variata'where id=(select hr from q_test);
set local role authenticated;
do $$declare t record;c record;q jsonb;begin select * into t from q_test;select * into c from contesto_test;
 q:=public.sicurezza_addetti_commessa(t.azienda,c.ordine,'2026-11-10','2026-11-15',c.fase);
 if q->>'impronta'=c.quadro->>'impronta' then raise exception 'ASSERT: mansione variata non rilevata';end if;
end$$;
reset role;
set local role authenticated;

do $$declare t record;c record;q jsonb;righe jsonb;d jsonb;r jsonb;begin select * into t from q_test;select * into c from contesto_test;
 perform public.sicurezza_salva_profilo(c.profilo,t.azienda,null,jsonb_build_object('nome','TEST Requisiti PLE','attivita','Uso della piattaforma','ruoli','Addetti alla conduzione','limiti','TEST proposta da adattare','testi_generici',true,'criteri',jsonb_build_array(jsonb_build_object('id',c.criterio,'titolo','TEST Requisito nominativo','catalogo_id',null,'catalogo_versione',null,'riferimento','TEST fonte','indicazioni','Verificare originale e pertinenza'))));
 q:=public.sicurezza_addetti_commessa(t.azienda,c.ordine,'2026-11-10','2026-11-15',c.fase);
 select jsonb_agg(jsonb_build_object('persona_tipo',p->>'tipo','persona_id',p->>'id','profilo_id',c.profilo,'requisito_id',c.criterio,'esito','riesaminata','qualifica_id',(select a->>'id'from jsonb_array_elements(q->'qualifiche')a where a->>'persona_tipo'=p->>'tipo' and a->>'persona_id'=p->>'id'),'motivazione','TEST pertinenza controllata','confermata',true)order by p->>'tipo',p->>'id')into righe from jsonb_array_elements(q->'persone')p;
 d:=jsonb_build_object('attivita','TEST uso PLE','responsabile','TEST referente','ruolo_responsabile','TEST responsabile tecnico','requisiti',jsonb_build_array(jsonb_build_object('profilo_id',c.profilo,'requisito_id',c.criterio)),'righe',righe,'requisiti_definiti',true,'conferma_assegnazioni',true,'attrezzatura',null);
 perform public.sicurezza_registra_addetti(c.verifica,t.azienda,c.ordine,c.fase,'2026-11-10','2026-11-15',null,q->>'impronta',d);
 begin perform public.pos_riesame_proprio(t.azienda,c.ordine,c.verifica);raise exception 'ASSERT: propria identità irrisolta accettata';exception when raise_exception then if sqlerrm not like 'Collegamenti della propria%' then raise;end if;end;
 update contesto_test set dati_riesame=d;
end$$;
reset role;
-- Remove only the synthetic unmapped assignment, never real case data.
delete from public.order_employees where order_id=(select ordine from contesto_test) and employee_id=(select non_collegato from contesto_test);
set local role authenticated;
do $$declare t record;c record;q jsonb;d jsonb;r jsonb;begin select * into t from q_test;select * into c from contesto_test;
 q:=public.sicurezza_addetti_commessa(t.azienda,c.ordine,'2026-11-10','2026-11-15',c.fase);d:=c.dati_riesame;
 r:=public.sicurezza_registra_addetti(c.verifica2,t.azienda,c.ordine,c.fase,'2026-11-10','2026-11-15',c.verifica,q->>'impronta',d);
 if r->>'stato'<>'parziale' then raise exception 'ASSERT: legacy esterno non conservato nel contesto generale';end if;
 r:=public.pos_riesame_proprio(t.azienda,c.ordine,c.verifica2);
 if jsonb_array_length(r->'persone')<>1 or jsonb_array_length(r->'riscontri')<>1 or r->'persone'->0->>'id'<>t.hr::text or r->'riscontri'->0->'qualifica'->>'id'<>t.r1::text then raise exception 'ASSERT: proiezione propria non nominativa';end if;
 if r::text like '%'||t.operaio::text||'%' or r::text like '%'||t.sub::text||'%' or r::text like '%TEST QUALIFICHE IMPRESA%' or r::text like '%hr-documenti%' or r::text like '%file_path%' or r::text like '%TEST DATO HR PRIVATO%' or r::text like '%TEST DATO SANITARIO%' or r::text like '%987654%' then raise exception 'ASSERT: dati esterni/riservati esportati';end if;
 update contesto_test set quadro=r;
 begin perform public.pos_riesame_proprio(gen_random_uuid(),c.ordine,c.verifica2);raise exception 'ASSERT: azienda estranea';exception when insufficient_privilege then null;end;
 begin perform public.pos_riesame_proprio(t.azienda,t.ordine,c.verifica2);raise exception 'ASSERT: commessa estranea';exception when insufficient_privilege then null;end;
 begin perform public.pos_riesame_proprio(t.azienda,c.ordine,c.verifica);raise exception 'ASSERT: riesame superato';exception when serialization_failure then null;end;
 -- Qualification revocation of the OTHER employer cannot invalidate the own-emitter projection.
 perform public.sicurezza_qualifica_registra(gen_random_uuid(),t.azienda,'esterno',t.operaio,t.r3,'revoca',null,null,null,'TEST revoca esterna');
 if public.pos_riesame_proprio(t.azienda,c.ordine,c.verifica2) is distinct from r then raise exception 'ASSERT: variazione esterna contamina impronta propria';end if;
 perform set_config('TimeZone','Europe/Rome',true);
 if public.pos_riesame_proprio(t.azienda,c.ordine,c.verifica2) is distinct from r then raise exception 'ASSERT: proiezione dipende dal fuso orario';end if;
 perform set_config('TimeZone','UTC',true);
end$$;
reset role;
do $$declare t record;c record;begin select * into t from q_test;select * into c from contesto_test;
 begin update public.hr_documenti set titolo='TEST ORIGINALE CAMBIATO'where id=t.doc_hr;perform public.pos_riesame_proprio_foto(t.azienda,c.ordine,c.verifica2,t.actor);raise exception 'ASSERT: originale cambiato';exception when serialization_failure then null;end;
 begin update public.hr_profili set mansione='TEST NUOVA MANSIONE'where id=t.hr;perform public.pos_riesame_proprio_foto(t.azienda,c.ordine,c.verifica2,t.actor);raise exception 'ASSERT: mansione cambiata';exception when serialization_failure then null;end;
 begin update storage.objects set version='TEST BYTE NUOVI'where bucket_id='hr-documenti' and name=t.azienda::text||'/'||t.hr::text||'/qualifica.pdf';perform public.pos_riesame_proprio_foto(t.azienda,c.ordine,c.verifica2,t.actor);raise exception 'ASSERT: byte originali cambiati';exception when serialization_failure then null;end;
 begin update public.hr_profili set attivo=false where id=t.hr;perform public.pos_riesame_proprio_foto(t.azienda,c.ordine,c.verifica2,t.actor);raise exception 'ASSERT: persona disattivata';exception when serialization_failure then null;end;
 if public.pos_riesame_proprio_foto(t.azienda,c.ordine,c.verifica2,t.actor) is distinct from c.quadro then raise exception 'ASSERT: effetti negativi non annullati';end if;
end$$;


create temporary table pos_addetti_test(pos_id uuid default gen_random_uuid(),contenuto jsonb,prova jsonb,emissione jsonb,manifest jsonb);
insert into pos_addetti_test default values;
grant select,update on q_test,contesto_test,pos_addetti_test to service_role,authenticated;
update pos_addetti_test set contenuto=jsonb_build_object('versione_modello',1,'versione_controlli',2,'versione_requisiti_addetti',1,'opera',jsonb_build_object('data_inizio','2026-11-01','data_fine','2026-11-30'),'formazione',jsonb_build_array(jsonb_build_object('nominativo',c.quadro->'persone'->0->>'nome'||' '||(c.quadro->'persone'->0->>'cognome'),'riferimento_addetto',jsonb_build_object('tipo','hr','id',t.hr))),'lavorazioni',jsonb_build_array(jsonb_build_object('id','TEST-lavorazione','fase_id',c.fase,'svolgimento','diretto','svolgimento_con','','titolo','TEST uso PLE','requisiti_addetti',jsonb_build_object('modalita','riesami','dal','2026-11-10','al','2026-11-15','motivazione','','adattamento','TEST conduzione PLE con i limiti riesaminati','fonti',jsonb_build_array(jsonb_build_object('id',c.verifica2,'impronta',c.quadro->>'impronta','fotografia',c.quadro)),'confermata',true,'contesto_lavorazione',jsonb_build_object('id','TEST-lavorazione','fase_id',c.fase,'svolgimento','diretto','svolgimento_con','','titolo','TEST uso PLE')))))from contesto_test c cross join q_test t;
set local role service_role;
do $$declare t record;c record;p record;q jsonb;x jsonb;begin select * into t from q_test;select * into c from contesto_test;select * into p from pos_addetti_test;
 q:=public.pos_requisiti_addetti_verifica(t.azienda,c.ordine,p.contenuto,t.actor);
 if jsonb_array_length(q->'collegamenti')<>1 or jsonb_array_length(q->'allegati')<>1 or q->'allegati'->0->>'persona_id'<>t.hr::text or q->'allegati'->0->>'evidenza_id'<>t.doc_hr::text or q->'allegati'->0->>'bucket'<>'hr-documenti' then raise exception 'ASSERT: prova originale non canonica';end if;
 update pos_addetti_test set prova=q;
 begin update public.sicurezza_profili_requisiti set id=gen_random_uuid() where id=c.profilo;raise exception 'ASSERT: ID profilo mutabile dal servizio';exception when raise_exception then if sqlerrm not like 'I contenuti del profilo non si sovrascrivono%'then raise;end if;end;
 begin update public.sicurezza_profili_requisiti set archiviato=true where id=c.profilo;raise exception 'ASSERT: il grant di lock permette archiviazione diretta';exception when insufficient_privilege then null;end;

 x:=public.pos_originale_addetto_per_autore(t.azienda,c.ordine,c.verifica2,t.hr,t.doc_hr,c.quadro->'riscontri'->0->'qualifica'->>'fonte_impronta',t.actor);
 if x->>'path'<>t.azienda::text||'/'||t.hr::text||'/qualifica.pdf' then raise exception 'ASSERT: percorso originale non canonico';end if;
 if public.pos_originale_addetto_per_autore(t.azienda,c.ordine,c.verifica2,t.hr,t.doc_hr,c.quadro->'riscontri'->0->'qualifica'->>'fonte_impronta',t.sicurezza_actor) is distinct from x then raise exception 'ASSERT: lettore Sicurezza escluso dall’originale pertinente';end if;
 begin perform public.pos_originale_addetto_per_autore(t.azienda,c.ordine,c.verifica2,t.hr,t.doc_privato,repeat('a',64),t.actor);raise exception 'ASSERT: documento sanitario firmabile';exception when insufficient_privilege then null;end;
 begin perform public.pos_originale_addetto_per_autore(t.azienda,c.ordine,c.verifica2,t.altro_hr,t.doc_hr,repeat('a',64),t.actor);raise exception 'ASSERT: omonimo originale firmabile';exception when insufficient_privilege then null;end;

 begin perform public.pos_requisiti_addetti_verifica(t.azienda,c.ordine,jsonb_set(p.contenuto,'{lavorazioni,0,titolo}','"TEST lavorazione diversa"'),t.actor);raise exception 'ASSERT: lavorazione cambiata ancora confermata';exception when raise_exception then if sqlerrm not like 'Riesamina i requisiti%'then raise;end if;end;
 x:=jsonb_set(p.contenuto,'{lavorazioni,0,requisiti_addetti,fonti,0,fotografia,riscontri,0,nominativo}','"TEST NOME FALSO"');
 begin perform public.pos_requisiti_addetti_verifica(t.azienda,c.ordine,x,t.actor);raise exception 'ASSERT: fotografia nominativa falsificata';exception when serialization_failure then null;end;
 begin perform public.pos_requisiti_addetti_verifica(t.azienda,c.ordine,jsonb_set(p.contenuto,'{formazione}','[]'),t.actor);raise exception 'ASSERT: identità formazione non allineata';exception when raise_exception then if sqlerrm not like 'Allinea l’identità%'then raise;end if;end;
 x:=jsonb_set(p.contenuto,'{lavorazioni,0,requisiti_addetti,dal}','"2026-11-09"');
 begin perform public.pos_requisiti_addetti_verifica(t.azienda,c.ordine,x,t.actor);raise exception 'ASSERT: periodo oltre riesame';exception when raise_exception then if sqlerrm not like 'Riesame non pertinente%'then raise;end if;end;
 x:=jsonb_set(p.contenuto,'{lavorazioni,0,requisiti_addetti,fonti}',jsonb_build_array(p.contenuto->'lavorazioni'->0->'requisiti_addetti'->'fonti'->0,p.contenuto->'lavorazioni'->0->'requisiti_addetti'->'fonti'->0));
 begin perform public.pos_requisiti_addetti_verifica(t.azienda,c.ordine,x,t.actor);raise exception 'ASSERT: riesame duplicato';exception when raise_exception then if sqlerrm not like 'Riferimento al riesame%'then raise;end if;end;
 begin perform public.pos_requisiti_addetti_verifica(t.azienda,c.ordine,p.contenuto,null);raise exception 'ASSERT: autore assente';exception when insufficient_privilege then null;end;
end$$;
reset role;
insert into public.pos_documents(id,company_id,order_id,tipo_lavori,indirizzo_cantiere,status,revisione,contenuto,iter,updated_at)select p.pos_id,t.azienda,c.ordine,'TEST POS REQUISITI ROLLBACK','TEST Indirizzo','bozza',0,p.contenuto,'{}',clock_timestamp()from pos_addetti_test p cross join q_test t cross join contesto_test c;
set local role authenticated;
do $$declare t record;p record;begin select * into t from q_test;select * into p from pos_addetti_test;
 begin update public.pos_documents set contenuto=contenuto-'versione_requisiti_addetti'where id=p.pos_id;raise exception 'ASSERT: downgrade del protocollo';exception when serialization_failure then null;end;
 begin perform public.pos_requisiti_addetti_verifica(t.azienda,(select ordine from contesto_test),p.contenuto,t.actor);raise exception 'ASSERT: helper fonti direttamente eseguibile';exception when insufficient_privilege then null;end;
end$$;
reset role;
set local role service_role;
update pos_addetti_test d set emissione=public.pos_prenota_emissione(d.pos_id,t.actor,p.updated_at,null)from q_test t cross join public.pos_documents p where p.id=d.pos_id;
update pos_addetti_test d set prova=public.pos_requisiti_addetti_fonti_emissione(d.pos_id,t.actor)from q_test t;
reset role;
insert into storage.objects(bucket_id,name,metadata)select 'pos-emissioni',t.azienda::text||'/'||(d.emissione->>'id')||'/'||(d.emissione->>'token')||'/'||nome,'{"size":1}'from pos_addetti_test d cross join q_test t cross join unnest(array['POS.pdf','manifest.json','fascicolo.zip','FORMAZIONE.pdf'])nome;
update pos_addetti_test d set manifest=jsonb_build_object('versione',1,'emissioneId',d.emissione->>'id','companyId',t.azienda,'posId',d.pos_id,'revisione',0,'origine','approvazione_corrente','file',(select jsonb_agg(jsonb_build_object('nome',nome,'path',t.azienda::text||'/'||(d.emissione->>'id')||'/'||(d.emissione->>'token')||'/'||nome,'sha256',repeat('a',64),'dimensione',1,'ruolo',case when nome='POS.pdf' then 'pdf' else 'fonti' end))from unnest(array['POS.pdf','manifest.json','fascicolo.zip'])nome))from q_test t;
set local role service_role;
do $$declare t record;d record;x jsonb;begin select * into t from q_test;select * into d from pos_addetti_test;
 begin perform public.pos_completa_emissione((d.emissione->>'id')::uuid,(d.emissione->>'token')::uuid,t.actor,'TEST',d.manifest,repeat('b',64),repeat('c',64));raise exception 'ASSERT: manifest nominativo assente';exception when raise_exception then if sqlerrm<>'Il pacchetto non conserva i riscontri nominativi riesaminati'then raise;end if;end;
 x:=d.manifest||jsonb_build_object('requisiti_addetti',jsonb_build_object('versione',1,'collegamenti',d.prova->'collegamenti'));
 begin perform public.pos_completa_emissione((d.emissione->>'id')::uuid,(d.emissione->>'token')::uuid,t.actor,'TEST',x,repeat('b',64),repeat('c',64));raise exception 'ASSERT: originale formativo mancante';exception when raise_exception then if sqlerrm<>'Numero di originali formativi incoerente nel pacchetto'then raise;end if;end;
end$$;
reset role;
update pos_addetti_test d set manifest=d.manifest||jsonb_build_object('requisiti_addetti',jsonb_build_object('versione',1,'collegamenti',d.prova->'collegamenti'),'file',(d.manifest->'file')||jsonb_build_array(jsonb_build_object('nome','FORMAZIONE.pdf','path',t.azienda::text||'/'||(d.emissione->>'id')||'/'||(d.emissione->>'token')||'/FORMAZIONE.pdf','sha256',repeat('d',64),'dimensione',1,'ruolo','allegato','tipo','qualifica_addetto','evidenza_id',t.doc_hr,'persona_id',t.hr,'impronta_metadati',d.prova->'allegati'->0->>'impronta','fonte',jsonb_build_object('bucket','hr-documenti','path',d.prova->'allegati'->0->>'path'))))from q_test t;
set local role service_role;
do $$declare t record;d record;r jsonb;begin select * into t from q_test;select * into d from pos_addetti_test;
 begin update public.hr_documenti set titolo='TEST originale cambiato durante rendering' where id=t.doc_hr;perform public.pos_completa_emissione((d.emissione->>'id')::uuid,(d.emissione->>'token')::uuid,t.actor,'TEST',d.manifest,repeat('b',64),repeat('c',64));raise exception 'ASSERT: originale variato durante rendering accettato';exception when serialization_failure then null;end;
 r:=public.pos_completa_emissione((d.emissione->>'id')::uuid,(d.emissione->>'token')::uuid,t.actor,'TEST NOMINATIVO',d.manifest,repeat('b',64),repeat('c',64));
 if r->>'stato'<>'completa' then raise exception 'ASSERT: completamento fallito';end if;
end$$;
reset role;

set local role authenticated;
do $$declare p record;v jsonb;begin select * into p from public.pos_documents where id=(select pos_id from pos_addetti_test);
 perform public.pos_apri_revisione(p.id,'TEST revisione senza ereditare conferme',p.updated_at);
 select contenuto into v from public.pos_documents where id=p.id;
 if v->'lavorazioni'->0->'requisiti_addetti'->'confermata' is distinct from 'false'::jsonb or v->'lavorazioni'->0->'requisiti_addetti'->'contesto_lavorazione' is distinct from 'null'::jsonb then raise exception 'ASSERT: nuova revisione eredita conferme nominative';end if;
 if not exists(select 1 from public.pos_contenuti_archiviati a where a.pos_id=p.id and a.revisione=0 and a.snapshot->'contenuto'->'lavorazioni'->0->'requisiti_addetti'->'confermata'='true'::jsonb)then raise exception 'ASSERT: fotografia approvata alterata dalla nuova revisione';end if;
end$$;
reset role;
select 'PASS: requisiti nominativi, fonti service-only, contesto/fase/periodo/identità, manomissioni, guardie e pacchetto con rollback; metadata, nessun upload fisico' as risultato;
rollback;
